/** Native stat identities are unsigned; Node BigIntStats preserves them as signed bits. */
export function statIdentityFromNative(value) {
    return value <= 0x7fffffffffffffffn || process.versions.bun ? value : BigInt.asIntN(64, value);
}
export function isNativeStatIdentity(value) {
    return typeof value === "bigint" && value >= 0n && value <= 0xffffffffffffffffn;
}
